def _is_f(value):
    """F 判定：type(v) 为 int 或 float（不含 bool），float(v) 转换成功
    且有限。超大整数（float 转换溢出）不满足 F。"""
    if type(value) is not int and type(value) is not float:
        return False
    try:
        fv = float(value)
    except (OverflowError, ValueError):
        return False
    return math.isfinite(fv)

